<script setup lang="ts">
import type { ToolSettings } from '../types'
import { statusLabels } from '../utils'
import UseCategorySelect from './UseCategorySelect.vue'
const settings = defineModel<ToolSettings>('settings', { required: true })
const category = defineModel<string>('category', { required: true })
function addSource() { (settings.value.sources ||= []).push({ method: '', provider: '', timing: '局外', conditions: '', price: '' }) }
</script>
<template><div class="tool-fields"><div class="field"><span class="field-label">使用类别</span><UseCategorySelect v-model="category" /></div><div class="field"><label>触发方式<input v-model="settings.trigger" placeholder="例如：瞄准道具后按 F；或受到伤害时触发" maxlength="20000" /></label></div><div class="field"><label>效果说明<textarea v-model="settings.effect" rows="3" placeholder="效果、作用对象及限制，均可先用文字记录" maxlength="20000"></textarea></label></div><div class="field"><span class="field-label">获得来源</span><article v-for="(source,index) in settings.sources" :key="index" class="source-card"><div class="field-inline"><label>获取方式<select v-model="source.method" aria-label="获取方式"><option value="">待定</option><option v-for="method in ['购买','NPC 赠送','任务奖励','事件奖励','成就解锁','合成获得','初始持有','其他']" :key="method">{{ method }}</option></select></label><label>获得时机<select v-model="source.timing"><option>局外</option><option>局内</option><option>待定</option></select></label></div><label>提供者／地点<input v-model="source.provider" maxlength="4000" placeholder="例如：奶奶、局外商店" /></label><label>获得条件<textarea v-model="source.conditions" rows="2" maxlength="4000"></textarea></label><label v-if="source.method === '购买'">价格<input v-model="source.price" maxlength="4000" placeholder="待定；免费请填写 0" /></label><button type="button" class="text-button danger-text" @click="settings.sources.splice(index,1)">移除此来源</button></article><p v-if="!settings.sources?.length" class="muted">获取途径待补充，可以记录多条来源。</p><button type="button" class="secondary small" @click="addSource">＋ 添加来源</button></div><details class="supplement"><summary>使用限制与制作进度</summary><div class="field-inline"><label>冷却<input v-model="settings.cooldown" maxlength="20000" placeholder="待定，例如 30 秒" /></label><label>次数／充能<input v-model="settings.charges" maxlength="20000" placeholder="待定，例如每局 3 次" /></label></div><label>消耗规则<input v-model="settings.consumption" maxlength="20000" placeholder="待定，例如使用后保留道具" /></label><label>生效范围／持有期限<input v-model="settings.duration" maxlength="20000" placeholder="待定，例如本局有效、永久持有" /></label><div class="field-inline"><label>模型进度<select v-model="settings.model_status"><option value="">待定</option><option v-for="key in ['concept','design','production','completed']" :key="key" :value="key">{{ statusLabels[key] }}</option></select></label><label>功能进度<select v-model="settings.function_status"><option value="">待定</option><option v-for="key in ['concept','design','production','completed']" :key="key" :value="key">{{ statusLabels[key] }}</option></select></label></div></details></div></template>
